// Author: MiYu. Original CampaignAI startup and deferred live campaign army/economy checks share one source-backed session.
#include "session.h"
#include "setup.h"
#include <bit>
#include <cmath>
#include <iostream>
using namespace war3;
namespace {float number(jass::Real value){return std::bit_cast<float>(value.bits());}}
int wmain(int argc,wchar_t** argv){
    try{
        if(argc<3 || argc>4)throw std::runtime_error("Usage: war3_campaign_ai_tests <data-root> <fixture> [startup|armies|harvest|captain-home]");std::wstring mode=argc==4?argv[3]:L"startup";if(mode!=L"startup" && mode!=L"armies" && mode!=L"harvest" && mode!=L"captain-home")throw std::runtime_error("Unknown campaign check mode");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());setup.control(1,SlotControl::ComputerNormal);session.applySetup(setup);session.startMain();session.advance(4);auto& ai=*session.ais()[0];auto& vm=*ai.runtime;auto& map=session.runtime();auto call=[](jass::Runtime& runtime,const char* name,std::initializer_list<jass::Value> args){return runtime.invoke(name,{args.begin(),args.size()});};auto require=[](bool value,const char* message){if(!value)throw std::runtime_error(message);};auto type=ObjectData::code("hfoo");auto footman=vm.integer(std::bit_cast<int>(type));
        unsigned gathering=0,queued=0;for(auto& [id,u]:session.units())if(u->owner==0){gathering+=u->gather.phase!=GatherOrder::Phase::None;queued+=unsigned(u->production.size());}std::cout<<"startup_state opened="<<vm.global("campaign_opened").bits<<" towns="<<ai.towns.size()<<" threads="<<session.runtime().threadCount()<<" gathering="<<gathering<<" queued="<<queued<<'\n';require(ai.campaign && ai.slowChopping && !ai.newHeroes && !ai.groupTimedLife && vm.global("campaign_opened").bits && session.runtime().threadCount()>=2 && gathering>0 && queued>0,"Original CampaignAI did not reach its gather/build threads");std::cout<<"PASS original_campaign_startup threads="<<session.runtime().threadCount()<<" gathering="<<gathering<<" queued="<<queued<<'\n';
        if(mode==L"captain-home"){
            auto town=ai.townHome;auto set=[&](int mask,int x,int y){call(vm,"SetCaptainHome",{vm.integer(mask),vm.real(jass::Real::fromInteger(x)),vm.real(jass::Real::fromInteger(y))});};auto same=[](WorldPoint a,WorldPoint b){return a.x.bits()==b.x.bits() && a.y.bits()==b.y.bits();};auto original=ai.home;set(0,10,20);require(same(ai.home,original) && same(ai.defenseHome,town),"Zero captain mask changed a home");set(2,-1400,-1600);auto defense=ai.defenseHome;require(same(ai.home,original) && number(defense.x)==-1400 && same(ai.townHome,town),"Defense captain changed attack or town home");set(1,1200,1000);require(number(ai.home.x)==1200 && same(ai.defenseHome,defense) && same(ai.townHome,town),"Attack captain changed defense or town home");set(3,-1000,-1100);require(same(ai.home,ai.defenseHome) && number(ai.home.x)==-1000,"Combined captain mask did not update both homes");set(1,1200,1000);set(2,-1400,-1600);call(vm,"AddDefenders",{vm.integer(2),footman});require(ai.defenderUnits.size()==2,"Defense captain did not form");for(auto id:ai.defenderUnits)call(map,"IssueImmediateOrder",{map.handle("unit",id),map.string("stop")});session.advance(2);bool marching=false;for(auto id:ai.defenderUnits){auto u=session.units().at(id);if(u->currentOrder==851986 && !u->route.empty()){auto end=u->route.back();marching|=std::hypot(number(end.x)-number(ai.defenseHome.x),number(end.y)-number(ai.defenseHome.y))<std::hypot(number(u->x)-number(ai.defenseHome.x),number(u->y)-number(ai.defenseHome.y));}}require(marching && same(ai.townHome,town),"Defense captain did not march toward its own home");std::cout<<"PASS captain_home_masks_and_defense_march\n";
        }
        if(mode==L"armies"){
            call(vm,"AddAssault",{vm.integer(2),footman});call(vm,"AddDefenders",{vm.integer(2),footman});require(ai.captain.size()==2 && ai.defenderUnits.size()==2,"Captain goals did not reserve distinct units");for(auto id:ai.captain)require(!ai.defenderUnits.contains(id),"Attack and defense membership overlaps");auto p0=call(map,"Player",{map.integer(0)});auto reserve=call(map,"CreateUnit",{p0,map.integer(std::bit_cast<int>(type)),map.real(jass::Real::fromInteger(-900)),map.real(jass::Real::fromInteger(-900)),map.real({})});call(vm,"SetCaptainChanges",{vm.boolean(false)});auto lost=*ai.captain.begin();call(map,"RemoveUnit",{map.handle("unit",lost)});session.advance(1);require(ai.captain.size()==1 && !ai.captain.contains(reserve.bits),"Disabled automatic replacement changed captains");call(vm,"SetCaptainChanges",{vm.boolean(true)});require(ai.captain.size()==2 && ai.captain.contains(reserve.bits),"Enabled automatic replacement did not enroll reserve");call(vm,"TeleportCaptain",{vm.real(jass::Real::fromInteger(-1000)),vm.real(jass::Real::fromInteger(-1000))});float x=0,y=0;for(auto id:ai.captain){auto u=session.units().at(id);require(!u->currentOrder && u->route.empty(),"Teleport left an old order or route");x+=number(u->x);y+=number(u->y);}require(std::abs(x/2+1000)<1 && std::abs(y/2+1000)<1,"Teleport did not preserve relative formation at destination");auto unitCount=session.units().size();call(vm,"SuicideUnitEx",{vm.integer(1),footman,vm.integer(1)});require(ai.suicideUnits.size()==1 && session.units().size()==unitCount,"Suicide wave created or killed a unit");auto id=ai.suicideUnits.begin()->first;auto u=session.units().at(id);require(!ai.captain.contains(id) && !ai.defenderUnits.contains(id) && !ai.guardUnits.contains(id) && (u->combat.target || u->combat.attackMove),"Suicide wave did not issue an isolated live attack");std::cout<<"PASS captain_replacement_teleport_and_suicide\n";
        }
        if(mode==L"harvest"){
            auto worker=map.global("worker"),tree=map.global("tree");call(vm,"StopGathering",{});auto u=session.units().at(worker.bits);auto d=session.destructables().at(tree.bits);call(map,"SetUnitPosition",{worker,map.real(d->position.x),map.real(d->position.y)});require(call(map,"IssueTargetOrder",{worker,map.string("harvest"),tree}).bits,"Worker could not harvest fixture tree");auto lumber=u->carriedLumber;auto life=d->life;session.advance(.03125);auto interval=u->gather.due-session.simulationTime();require(interval>0 && interval<60,"Fixture did not enter a chopping phase");session.advance(interval+.03125);require(u->carriedLumber==lumber+1 && std::abs(life-d->life-.1f)<.01f,"Campaign chopping did not separate tree damage from yield");call(vm,"SetSlowChopping",{vm.boolean(false)});call(vm,"ClearHarvestAI",{});call(vm,"HarvestGold",{vm.integer(0),vm.integer(1)});call(vm,"HarvestWood",{vm.integer(0),vm.integer(0)});session.advance(1);unsigned gold=0,wood=0;for(auto& [id,state]:session.units())if(state->owner==0){gold+=state->gather.mine!=0;wood+=state->gather.tree!=0;}require(gold<=1 && wood==0,"Reduced harvest quotas retained excess workers");std::cout<<"PASS campaign_chopping_and_harvest_rebalance\n";
        }
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"RESULT passed="<<(mode==L"startup"?1:2)<<" failed=0 game_dll_loaded=false\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
